/* Data-directory settings and persistent save feedback. */
(()=>{
 const S=AppStorage,L=(zh,en)=>I18n.getLanguage()==='en-US'?en:zh;
 const status=document.createElement('button');status.id='storageStatus';status.type='button';status.className='storage-status';status.setAttribute('aria-live','polite');status.title=L('打开数据保存设置','Open data storage settings');status.onclick=()=>{page='settings';render();document.getElementById('folderStorageSettings')?.scrollIntoView({block:'start',behavior:'instant'})};document.querySelector('.toolbar').prepend(status);S.paintStatus();
 const base=renderSettings;renderSettings=function(){base();const section=document.createElement('section');section.id='folderStorageSettings';section.className='folder-storage-settings';
  section.innerHTML='<h3>'+L('资料库保存位置','Library storage')+'</h3><p id="folderStorageDescription"></p><p id="folderStorageStatus" role="status"></p><div class="folder-storage-actions"><button id="connectDataFolder"></button><button id="saveDataFolder">'+L('立即保存','Save now')+'</button><button id="reauthorizeDataFolder">'+L('重新授权／重试','Reauthorize / retry')+'</button><button id="reloadDataFolder">'+L('重新载入磁盘版本','Reload disk version')+'</button><button id="browserDataMode">'+L('返回原浏览器副本','Use original browser copy')+'</button></div><div class="folder-storage-actions"><button id="downloadFullBackup">'+L('下载完整 JSON 备份','Download full JSON backup')+'</button><button id="folderSnapshotBackup">'+L('创建文件夹备份','Create folder backup')+'</button><button id="folderBackupList">'+L('查看可恢复备份','Show restorable backups')+'</button><button id="cacheFolderImages">'+L('下载／补齐离线图片','Download / complete offline images')+'</button><button id="cancelFolderImages" hidden>'+L('停止图片下载','Stop image download')+'</button></div><div id="folderBackupRows"></div><p>'+L('自动保留最近 5 个备份索引。海报和缩略图单独保存；未引用图片暂不自动删除。TMDb 凭据仅保存在此浏览器，不写入资料夹或普通备份。','Keeps the latest 5 backup manifests. Posters and stills are stored separately; unreferenced images are retained. TMDb credentials stay in this browser and are excluded from folders and ordinary backups.')+'</p>';
  document.querySelector('#extraSection .settings-panel').append(section);
  const folder=S.mode==='folder',desc=section.querySelector('#folderStorageDescription');desc.textContent=folder?L('当前文件夹：','Current folder: ')+S.connectionName():L('当前使用浏览器存储。连接专用文件夹后，资料将直接保存到文件夹；原浏览器副本保留。','Currently using browser storage. Connect a dedicated folder to save there; the browser copy is kept.');
  section.querySelector('#connectDataFolder').textContent=L(folder?'切换资料库文件夹':'连接本地资料库',folder?'Switch library folder':'Connect local library');
  for(const id of ['saveDataFolder','reauthorizeDataFolder','reloadDataFolder','browserDataMode','folderSnapshotBackup','folderBackupList','cacheFolderImages'])section.querySelector('#'+id).hidden=!folder;
  const report=section.querySelector('#folderStorageStatus');function bind(id,fn){const button=section.querySelector('#'+id);button.onclick=async()=>{button.disabled=true;try{const result=await fn();if(id==='cacheFolderImages'){report.textContent=result.cancelled?L('图片下载已停止，已完成的缓存和资料保留。','Image download stopped. Completed files and data are kept.'):result.failed?L('资料已保存，部分远程图片无法下载：','Data saved; remote images unavailable: ')+result.failed:L('图片已缓存，可离线显示。','Images cached for offline display.')}else if(id!=='folderBackupList')report.textContent=folder&&S.dirty?L('存在待保存更改','Changes are pending'):L('操作完成','Done')}catch(error){report.textContent=S.errorMessage(error)}finally{button.disabled=false}}}
  bind('connectDataFolder',()=>S.connect());bind('saveDataFolder',()=>S.flush());bind('reauthorizeDataFolder',()=>S.reauthorize());bind('reloadDataFolder',()=>S.reloadFolder());bind('browserDataMode',()=>S.useBrowser());bind('downloadFullBackup',()=>S.exportBackup());bind('folderSnapshotBackup',()=>S.makeBackup());
  bind('folderBackupList',async()=>{const rows=await S.repo.backups(),container=section.querySelector('#folderBackupRows');container.replaceChildren();if(!rows.length)container.textContent=L('暂无备份','No backups yet');for(const row of rows){const button=document.createElement('button');button.type='button';button.textContent=L('恢复：','Restore: ')+I18n.formatDate(row.date.slice(0,10))+' · '+row.date;button.onclick=async()=>{button.disabled=true;try{await S.restoreBackup(row.raw)}catch(error){report.textContent=S.errorMessage(error)}finally{button.disabled=false}};container.append(button)}});
  section.querySelector('#cancelFolderImages').onclick=()=>S.cancelImageDownload();bind('cacheFolderImages',async()=>{const cancel=section.querySelector('#cancelFolderImages');cancel.hidden=false;try{return await S.cacheImages((count,failed)=>{report.textContent=L('已处理图片：','Images processed: ')+count+L('，失败：',', failed: ')+failed})}finally{cancel.hidden=true}});
  // The original export remains compatible and now includes non-secret preferences.
  document.querySelector('#exportData').onclick=()=>S.exportBackup();S.paintStatus();
 };
 const originalSaveMessage=toast;toast=function(text){originalSaveMessage(S.saveMessage(String(text)))};
 // Object URLs are used only in presentation; the stored data retains remote identifiers.
 if(page==='settings')render();
})();
